def M(id, file, desc, *edits, equiv=None):
    """equiv: 同値ミュータント(外から観測できない変更)と判断した理由。生き残りが期待どおりであることを、スクリプトが確認する。"""
    return {"id": id, "file": file, "desc": desc, "edits": list(edits), "equiv": equiv}


